#include <bits/stdc++.h>
using namespace std;
struct Seg{int n; vector<int>mn,mx,imn,imx; vector<int>*a; Seg(vector<int>&v):n(v.size()),mn(4*n),mx(4*n),imn(4*n),imx(4*n),a(&v){build(1,0,n-1);} void build(int p,int l,int r){if(l==r){mn[p]=mx[p]=(*a)[l];imn[p]=imx[p]=l;return;}int m=(l+r)/2;build(p*2,l,m);build(p*2+1,m+1,r);pull(p);} void pull(int p){int x=p*2,y=x+1;if(mn[x]<=mn[y])mn[p]=mn[x],imn[p]=imn[x];else mn[p]=mn[y],imn[p]=imn[y];if(mx[x]>=mx[y])mx[p]=mx[x],imx[p]=imx[x];else mx[p]=mx[y],imx[p]=imx[y];} pair<int,int> query(int p,int l,int r,int ql,int qr,bool high){if(ql<=l&&r<=qr)return {high?mx[p]:mn[p],high?imx[p]:imn[p]};int m=(l+r)/2;pair<int,int> z=high?pair<int,int>{INT_MIN,-1}:pair<int,int>{INT_MAX,-1};if(ql<=m)z=query(p*2,l,m,ql,qr,high);if(qr>m){auto w=query(p*2+1,m+1,r,ql,qr,high);if((high&&w.first>z.first)||(!high&&w.first<z.first))z=w;}return z;}void upd(int p,int l,int r,int i){if(l==r){mn[p]=mx[p]=(*a)[l];return;}int m=(l+r)/2;if(i<=m)upd(p*2,l,m,i);else upd(p*2+1,m+1,r,i);pull(p);}};
int main(){ios::sync_with_stdio(0);cin.tie(0);int n,m;cin>>n>>m;vector<int>a(n);for(int&x:a)cin>>x;Seg s(a);while(m--){int l,r;cin>>l>>r;--l;--r;int i=s.query(1,0,n-1,l,r,0).second,j=s.query(1,0,n-1,l,r,1).second;swap(a[i],a[j]);s.upd(1,0,n-1,i);s.upd(1,0,n-1,j);}for(int i=0;i<n;i++)cout<<a[i]<<(i+1==n?'\n':' ');}
